Q=Path('docs/auditorias/engenharia-qualidade-noturna-20261014/ENGENHARIA-QUALIDADE');p=Q/'CONTRATOS-BRANCHES.json';d=json.loads(p.read_text(encoding='utf-8'));rows=[]
