  rows.append(dict(branch=branch['branch'],funcao=f['name'],origem=kind,mesmo_corpo_presente=f['same_body_present'],fontes_horas=';'.join(x['file']for x in f['ours']),fontes_branch=';'.join(x['file']for x in f['theirs']),limite='Corpo/hash divergente exige semântica e ordem de instalação; não prova catálogo real.'))
